<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/sales_step15.php';if(empty($_SESSION['fulfillment_csrf']))$_SESSION['fulfillment_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['fulfillment_csrf'];$error=null;$success=null;$sales=[];$customers=[];
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'');$orderId=(int)($_POST['order_id']??0);if($action==='link_customer'){$raw=trim((string)($_POST['customer_id']??''));sales_step15_link_customer($pdo,$orderId,$raw===''?null:(int)$raw);$success='Customer linkage for Order #'.$orderId.' updated.';}elseif($action==='invoice'){$id=sales_step15_generate_invoice($pdo,$orderId,(string)($_POST['invoice_date']??date('Y-m-d')));$success='Sales Invoice #'.$id.' ready.';}}$sales=sales_step15_sales_rows($pdo,$orgId);$customers=sales_step15_customers($pdo,$orgId);}catch(Throwable $e){$error=$e->getMessage();}
function sf_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function sf_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Sales Fulfillment - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • Sales Fulfillment</small></span></a><div class="os-top-actions"><a class="os-btn" href="customer_center.php">Customers</a><a class="os-btn" href="sales_receivables.php">Receivables</a><a class="os-btn primary" href="product_sales_center.php">Product Sales</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">After-Sales</div><nav class="os-nav"><a href="customer_center.php"><i class="dot"></i>Customers</a><a class="active" href="sales_fulfillment.php"><i class="dot"></i>Fulfillment</a><a href="sales_invoice.php"><i class="dot"></i>Invoices</a><a href="sales_delivery.php"><i class="dot"></i>Delivery</a><a href="sales_returns.php"><i class="dot"></i>Returns</a><a href="sales_refunds.php"><i class="dot"></i>Refunds</a><a href="sales_receivables.php"><i class="dot"></i>Receivables</a><a href="crm_followups.php"><i class="dot"></i>Follow-ups</a><a href="step15_audit.php"><i class="dot"></i>STEP 15 Audit</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 15B • SALES FULFILLMENT CONTROL</div><h1>Move each finalized Product Sale from customer identity to invoice, delivery and after-sales.</h1><p>Original sale stays immutable as source evidence. Returns create separate credit notes; refunds stay separate from received payments.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'FULFILLMENT LIVE':'Review required' ?></span><span class="os-chip"><?= count($sales) ?> product sales</span><span class="os-chip"><?= count($customers) ?> customer master records</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Fulfillment diagnostic:</strong> <?= sf_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?= sf_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Sales Fulfillment Ledger</h2><p>Customer, invoice, delivery and financial after-sales status in one place.</p></div><a class="os-btn" href="product_order_builder.php">+ New Product Quote</a></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Order / Quote</th><th>Customer</th><th>Invoice</th><th>Delivery</th><th>Original</th><th>Returns</th><th>Collected</th><th>Refund</th><th>Receivable</th><th>Actions</th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td><b>#<?= (int)$s['order_id'] ?></b><small><?= sf_h($s['order_date'].' • '.($s['quote_code']?:'')) ?></small></td><td><b><?= sf_h($s['customer_name']) ?></b><small><?= $s['customer_id']?'Customer #'.(int)$s['customer_id']:'Snapshot only' ?></small><details><summary>Link / Change</summary><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= sf_h($csrf) ?>"><input type="hidden" name="action" value="link_customer"><input type="hidden" name="order_id" value="<?= (int)$s['order_id'] ?>"><select name="customer_id"><option value="">Keep snapshot only</option><?php foreach($customers as $c):?><option value="<?= (int)$c['id'] ?>" <?= (int)$s['customer_id']===(int)$c['id']?'selected':'' ?>><?= sf_h($c['customer_name'].' • '.$c['customer_code'].($c['mobile']?' • '.$c['mobile']:'')) ?></option><?php endforeach;?></select><button>Save Link</button></form></details></td><td><?php if($s['invoice_number']):?><a href="sales_invoice.php?order=<?= (int)$s['order_id'] ?>"><b><?= sf_h($s['invoice_number']) ?></b></a><?php else:?><span>Not generated</span><form method="post"><input type="hidden" name="csrf" value="<?= sf_h($csrf) ?>"><input type="hidden" name="action" value="invoice"><input type="hidden" name="order_id" value="<?= (int)$s['order_id'] ?>"><input type="hidden" name="invoice_date" value="<?= sf_h(date('Y-m-d')) ?>"><button>Generate</button></form><?php endif;?></td><td><b><?= sf_h(strtoupper($s['delivery_status'])) ?></b><small><a href="sales_delivery.php?order=<?= (int)$s['order_id'] ?>">Manage →</a></small></td><td><?= sf_m($s['original_charge']) ?></td><td><?= sf_m($s['return_credit']) ?></td><td><?= sf_m($s['net_collected']) ?></td><td><?= sf_m($s['refund_amount']) ?></td><td><b><?= sf_m($s['receivable_amount']) ?></b><?= (float)$s['customer_credit_due']>0?'<small>Credit due '.sf_m($s['customer_credit_due']).'</small>':'' ?></td><td><a href="sales_invoice.php?order=<?= (int)$s['order_id'] ?>">Invoice</a><br><a href="sales_returns.php?order=<?= (int)$s['order_id'] ?>">Return</a><br><a href="sales_refunds.php?order=<?= (int)$s['order_id'] ?>">Refund</a></td></tr><?php endforeach;?><?php if(!$sales):?><tr><td colspan="10">No finalized Product Sales yet. No fake sale is required.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?><div class="os-footer-note"><strong>Fulfillment rule:</strong> Customer Master linking is explicit; invoice freezes original sale; return/refund are separate after-sales facts.</div></main></div></body></html>